name Arcade;

define {
  struct Player {
    score: uint64;
    combo: uint32;
    bestCombo: uint32;
    plays: uint32;
    hits: uint32;
    lastBlock: uint64;   // when they last played
    name: string;        // the next slot
  };

  // pick a name, once (BUG has no revert, so no checks)
  function join(name: string calldata) {
    players[msg.sender].name = name;
    playerList.push(msg.sender);
  };

  // a copy of the caller's record in memory (BUG has no storage
  // references), written back once
  function play() {
    let player: Player = players[msg.sender];
    player.plays = player.plays + 1;
    player.lastBlock = block.number as uint64;
    players[msg.sender] = _turn(player);
  };

  // one turn: a miss resets the combo, a hit scores
  function _turn(player: Player) -> Player {
    let hit = _rolledHit();
    if (!hit) {
      return _resetCombo(player);
    }
    player.combo = player.combo + 1;
    player.hits = player.hits + 1;
    if (player.combo > player.bestCombo) {
      player.bestCombo = player.combo;
    }
    let gained = _applyCombo(10, player.combo);
    player.score = player.score + gained;
    totalScore = totalScore + gained;
    totalHits = totalHits + 1;
    return player;
  };

  // anyone may
  function setMotd(text: string calldata) {
    motd = text;
  };

  // a toy roll (not safe randomness): 2 in 3 is a hit. Equal to
  // Solidity's keccak256(abi.encode(block.prevrandao, msg.sender))
  function _rolledHit() -> bool {
    return (keccak256(block.prevrandao, msg.sender) as uint256) % 3 != 0;
  };

  function _resetCombo(player: Player) -> Player {
    player.combo = 0;
    return player;
  };

  function _applyCombo(points: uint64, combo: uint32) -> uint64 {
    let mult: uint64 = 5;   // the multiplier stops at 5
    if (combo < 5) {
      mult = combo;
    }
    return points * mult;
  };
}

storage {
  [0] playerList: array<address>;  // who joined, in order (a mapping can't list its keys)
  [1] motd: string;                // the message of the day
  [2] totalScore: uint128;         // every player's points
  [3] totalHits: uint64;           // every player's hits
  [4] players: mapping<address, Player>;
}

create {
  motd = "season 2 starts friday, see you on the leaderboard";
}

code {
  // join(string)
  if (msg.data[0:4] as bytes4 == 0x6a786b07) {
    let len = msg.data[36:68] as bytes32 as uint256;
    // (a calldata reference: the name stays in the call, no copy)
    let name: string calldata = msg.data[68:68 + len] as string calldata;
    join(name);
    return;
  }
  // play()
  if (msg.data[0:4] as bytes4 == 0x93e84cd9) {
    play();
    return;
  }
  // setMotd(string)
  if (msg.data[0:4] as bytes4 == 0x5fe59b9d) {
    let len = msg.data[36:68] as bytes32 as uint256;
    let text: string calldata = msg.data[68:68 + len] as string calldata;
    setMotd(text);
    return;
  }
}
